// SQL catalogue: the light part of the question bank (titles, levels, key points, follow-ups).
// Safe to import anywhere (e.g. the home page). Question text, table schemas and model answers live
// in content/*.js and are merged in by sql.js, which only the SQL pages import.
//
// `leetcode` is the slug of a similar LeetCode problem, so the student can run a query there.

const sq = (id, title, category, level, core, rubric, twist, leetcode = null) => ({
  id: `sql-q-${id}`,
  track: "queries",
  title,
  category,
  level,
  core,
  rubric,
  twist,
  leetcode,
});

const sc = (id, title, category, level, core, rubric, twist) => ({
  id: `sql-c-${id}`,
  track: "concepts",
  title,
  category,
  level,
  core,
  rubric,
  twist,
});

